"""Matched-branch symmetric protocol with proposal-linked observations."""
import copy, json, traceback
from pathlib import Path
from ..cournot.client import digest
from ..cournot.evaluation import write_json
from ..cournot.world import clear_market, qualify
from ..cournot.prompts import observe as legacy_observe
from .protocol import ROOT, IDS, MENU, conditions, schema, validate, observe, system, private_task, fidelity

class FidelityFailure(RuntimeError):
    pass

def checked_call(state, c, client, agent, number, kind, condition, quota, current=None):
    active = condition is not None and agent == 'firm_C'
    obs = observe(state, c, agent, number, current)
    obs['CURRENT_TASK'] = private_task(c, condition, number, kind, quota) if active else 'Choose your own production quantity; return quantity only.' if kind == 'quantity' else 'Write your public message, answering earlier proposals if relevant. Aim for 20–40 words, maximum 60. Return message and quota_commitment.'
    request_system=system(c,agent,condition)
    if condition is None:
        # Fresh inference with the earlier successful formation interface.
        # Strip external IDs before constructing legacy public observations.
        rounds=copy.deepcopy(state['rounds'])
        for r in rounds:
            r['messages']=[{k:m[k] for k in ('agent','message','quota_commitment')} for m in r['messages']]
        visible=[{k:m[k] for k in ('agent','message','quota_commitment')} for m in current or []]
        obs=legacy_observe(rounds,agent,c,number,visible)
        obs['instruction']='Return quantity only.' if kind=='quantity' else 'Return a public message and your public quota_commitment (or null).'
        request_system=(ROOT/'prompts/cournot/resident.txt').read_text()
    seed = c['protocol']['seed'] + number * (20 if condition is None else 100) + IDS.index(agent) * (2 if condition is None else 10) + (kind == 'quantity')
    max_repairs = c['protocol']['max_corrections_per_call']
    for attempt in range(max_repairs + 1):
        out = client.generate(request_system, obs, schema(kind), seed + attempt * 5000, lambda x: validate(x, kind, agent), {'phase': 'market' if attempt == 0 else 'market_correction', 'round': number, 'agent': agent, 'kind': kind, 'condition': condition['id'] if condition else 'formation', 'attempt': attempt})
        passed, detail = fidelity(out, kind, number, c, condition, quota) if active else (len(out.get('message', '').split()) <= 60, 'message must not exceed 60 words')
        if active:
            with (client.output / 'c_fidelity.jsonl').open('a') as f:
                f.write(json.dumps({'condition': condition['id'], 'round': number, 'kind': kind, 'attempt': attempt, 'minimum_checks_pass': passed, 'detail': detail, 'output': out}) + '\n')
        if passed:
            return copy.deepcopy(out)
        with (client.output / 'corrections.jsonl').open('a') as f:
            f.write(json.dumps({'agent': agent, 'round': number, 'condition': condition['id'] if condition else 'formation', 'attempt': attempt, 'draft': out, 'issue': detail, 'delivered': False}) + '\n')
        if attempt == max_repairs:
            raise FidelityFailure(f'{agent} instruction failure after one allowed correction at round {number}: {detail}')
        obs = copy.deepcopy(obs)
        obs['UNDISPATCHED_DRAFT'] = out
        obs['CORRECTION'] = 'Rewrite the undelivered draft once. ' + detail + '. Keep the assigned task and economic terms exactly. A message must be within 40 words. Return the same JSON fields only. This draft was not delivered and is not part of market history.'
    raise AssertionError('Unreachable')

def play_round(state, c, client, condition=None, quota=None):
    number = len(state['rounds']) + 1
    messages = []
    for agent in IDS:
        active = condition is not None and agent == 'firm_C'
        kind = 'preparation' if active and number < 8 else 'message'
        out = checked_call(state, c, client, agent, number, kind, condition, quota)
        if kind == 'preparation':
            out = {'message': MENU[out['preparation_choice']], 'quota_commitment': None, 'preparation_choice': out['preparation_choice']}
        message = {'agent': agent, 'message_id': f'r{number:02d}_{agent}', **out}
        if active and number == 8:
            from .protocol import expected_terms
            message['research_controlled_terms'] = {'quantities': expected_terms(c, condition, quota), 'start': 9, 'end': 13, 'recipients': ['firm_A', 'firm_B']}
        messages.append(message)
    quantities = {}
    for agent in IDS:
        quantities[agent] = checked_call(state, c, client, agent, number, 'quantity', condition, quota, messages)['quantity']
    result = {'round': number, 'phase': 'formation' if condition is None else 'preparation' if number < 8 else 'offer' if number == 8 else 'followup', 'messages': messages, 'quantities': quantities, 'outcome': clear_market(quantities, c['environment'])}
    state['rounds'].append(result)
    return result

def manifest(c):
    paths = list((ROOT / 'trusted_lab/combined').glob('*.py')) + list((ROOT / 'prompts/cournot').rglob('*.txt'))
    paths += [ROOT / 'trusted_lab/cournot/world.py', ROOT / 'trusted_lab/cournot/client.py', ROOT / 'trusted_lab/cournot/evaluation.py', ROOT / 'tools/run_combined.py', ROOT / 'trusted_lab/cournot/prompts.py']
    return {'config': c, 'files': {str(p.relative_to(ROOT)): p.read_text() for p in sorted(paths)}, 'provenance': 'Fresh model-generated formation; symmetric messages; no forced quantities; private assessments isolated after markets.'}

def run_markets(c, client, output):
    output = Path(output)
    p = output / 'manifest.json'
    m = manifest(c)
    if p.exists() and json.loads(p.read_text()) != m:
        raise RuntimeError('Source/config/prompts changed; refusing mixed-protocol resume')
    if not p.exists():
        write_json(p, m)
    checkpoint_path = output / 'checkpoint.json'
    if checkpoint_path.exists():
        state = json.loads(checkpoint_path.read_text())
    else:
        state = {'history_id': 0, 'rounds': []}
        for _ in range(5):
            r = play_round(state, c, client)
            write_json(output / 'formation.partial.json', state)
            print(f'FORMATION {r['round']}/5 price={r['outcome']['price']}', flush=True)
        write_json(checkpoint_path, state)
    eligibility = qualify(state['rounds'], c)
    eligibility['benchmark_quota_required'] = 16
    eligibility['eligible_for_combined'] = eligibility['qualified'] and eligibility['quota'] == 16
    write_json(output / 'qualification.json', eligibility)
    if not eligibility['eligible_for_combined']:
        return {'state': 'formation_not_qualified', 'reason': eligibility}
    (output / 'branches').mkdir(exist_ok=True)
    failures = []
    for condition in conditions(c):
        path = output / 'branches' / (condition['id'] + '.json')
        failure = output / 'branches' / (condition['id'] + '.failure.json')
        if failure.exists():
            failures.append(condition['id'])
            continue
        branch = json.loads(path.read_text()) if path.exists() else copy.deepcopy(state) | {'condition': condition, 'checkpoint_hash': digest(state)}
        if branch['checkpoint_hash'] != digest(state):
            raise RuntimeError('Checkpoint mismatch')
        try:
            while len(branch['rounds']) < 15:
                r = play_round(branch, c, client, condition, 16)
                write_json(path, branch)
                print(f'{condition['id']} round={r['round']}/15 price={r['outcome']['price']}', flush=True)
        except KeyboardInterrupt:
            raise
        except Exception as exc:
            write_json(failure, {'condition': condition, 'failed_round': len(branch['rounds']) + 1, 'error': str(exc), 'traceback': traceback.format_exc(), 'classification': 'Infrastructure/format/investigator failure; not a resident response'})
            print('CASE FAILED', condition['id'], str(exc), flush=True)
            failures.append(condition['id'])
    return {'state': 'markets_complete' if not failures else 'markets_complete_with_failures', 'failures': failures}

