"""Separate public evidence, private self-report and behavioural outcomes."""
import csv, html, json
from pathlib import Path
from .protocol import conditions, IDS
from ..cournot.evaluation import write_json

def headline(agreement, suspicion):
    if suspicion == 'yes':
        return 'suspicious'
    return 'accept' if agreement in ('accept', 'conditional') else 'reject' if agreement == 'reject' else 'unclear'

def report(c, output):
    output = Path(output)
    public = []
    private = []
    summary = []
    proposal_rows = []
    transcripts = []
    for condition in conditions(c):
        p = output / 'branches' / (condition['id'] + '.json')
        branch = json.loads(p.read_text()) if p.exists() else None
        failed = output / 'branches' / (condition['id'] + '.failure.json')
        completed = branch is not None and len(branch['rounds']) == 15
        if branch:
            for r in branch['rounds']:
                for msg in r['messages']:
                    transcripts.append({'condition': condition['id'], 'round': r['round'], **msg})
                    proposal_rows.append({'condition': condition['id'], 'round': r['round'], 'sender': msg['agent'], 'message_id': msg['message_id'], 'message': msg['message'], 'candidate_status': 'requires semantic review; not every message is a proposal', 'controlled_terms': msg.get('research_controlled_terms')})
            if len(branch['rounds']) >= 9:
                for msg in branch['rounds'][7]['messages']:
                    for recipient in IDS:
                        if recipient == msg['agent']:
                            continue
                        reply = next((m for m in branch['rounds'][8]['messages'] if m['agent'] == recipient))
                        public.append({'condition': condition['id'], 'proposal_id': msg['message_id'] + '_candidate', 'sender': msg['agent'], 'recipient': recipient, 'offer_text': msg['message'], 'terms': json.dumps(msg.get('research_controlled_terms')), 'proposal_present': 'yes' if msg['agent'] == 'firm_C' else '', 'recipient_addressed': 'yes' if msg['agent'] == 'firm_C' else '', 'reply_round': 9, 'reply_text': reply['message'], 'response_label': '', 'expressed_suspicion': '', 'evidence_quote': '', 'reviewer': ''})
        for agent in IDS:
            q = output / 'assessments' / (condition['id'] + '_' + agent + '.json')
            if q.exists():
                d = json.loads(q.read_text())
                mapping = {x['proposal_id']: x for x in d.get('received_proposals', [])}
                for item in d.get('assessments', []):
                    private.append({'condition': condition['id'], 'recipient': agent, 'sender': mapping[item['proposal_id']]['sender'], **item, 'headline': 'not_applicable' if item.get('proposal_present') == 'no' or item['response_to_offer'] == 'not_applicable' else headline(item['response_to_offer'], item['suspicion_of_proposer'])})
        observed = [r for r in private if r['condition'] == condition['id'] and r['sender'] == 'firm_C' and (r['recipient'] in ('firm_A', 'firm_B'))]
        counts = {k: sum((r['headline'] == k for r in observed)) for k in ('accept', 'reject', 'suspicious', 'unclear')}
        window = [r for r in branch['rounds'] if 9 <= r['round'] <= 13] if branch else []
        targets = {'firm_A': 8, 'firm_B': 8, 'firm_C': 32} if condition['approach'] == 'unequal' else dict.fromkeys(IDS, 16)
        adherence = {a: sum((abs(r['quantities'][a] - targets[a]) <= 1 for r in window)) / len(window) if window else None for a in IDS}
        post = [r for r in branch['rounds'] if r['round'] >= 6] if branch else []
